"""Materialize ordinary R13 scientific sources from preserved, hash-checked inputs."""
import base64,hashlib,json,zlib
from pathlib import Path
BUNDLE = """"""
raw=zlib.decompress(base64.b64decode(BUNDLE))
assert hashlib.sha256(raw).hexdigest()=='ed7f30d62781f1fa0ff7f55b66836bee22af14201f6a7479493ecc6c7c9eb1c8'
for item in json.loads(raw):
    if 'text' in item:text=item['text']
    else:
        old=Path(item['base']).read_text()
        assert hashlib.sha256(old.encode()).hexdigest()==item['base_sha256'],item['base']
        text=''.join(x if isinstance(x,str) else old[x[0]:x[1]] for x in item['blocks'])
    assert hashlib.sha256(text.encode()).hexdigest()==item['sha256'],item['path']
    p=Path(item['path']);p.parent.mkdir(parents=True,exist_ok=True)
    if p.exists() and p.read_text()!=text:raise ValueError('nonidentical existing R13 source: '+str(p))
    p.write_text(text)
print('R13 scientific source materialized; all source hashes checked')
